    }
    return difficulty;
  }

  List<DifficultieEntity> getConfig() {
    final int selectLanguageIndex = StaticData.getLanguageIndex(language) ?? 0;
    final ConfigEntity configData =
        Get.find<ConfigController>().appConfig.value;
    final String languageCode =
        StaticData.languageList[selectLanguageIndex].value;
    final List<DifficultieEntity>? diffList =
        DifficultieUtils.getDifficultieList(configData, languageCode);
    if (diffList == null) return [];
    return diffList;
  }
